from mk import *
import math
G = 6.67e-11; M = 5.98e24; R = 6.37e6; GM = G * M
r1 = R + 7.2e5; r2 = R + 4.1e5
a1 = GM / r1 ** 2; v2 = math.sqrt(GM / r2); T2 = 2 * math.pi * r2 / v2 / 3600
Ed = GM * 300 / (2 * 6.9e6)
TF = ["נכון", "שגוי", "אי אפשר לקבוע"]

def fig():
    g = Fig(420, 290, "כדור הארץ ושני מסלולים מעגליים של הלוויין: בשלב הראשון בגובה 720 קילומטר, ובשלב השני בגובה 410 קילומטר")
    cx, cy = 210, 150
    g.circle(cx, cy, 90, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(cx, cy + 6, "כדור הארץ")
    g.circle(cx, cy, 108, fill="none", stroke="var(--d-line)", width=1.2, dash="4 4")
    g.circle(cx, cy, 130, fill="none", stroke="var(--d-line)", width=1.2, dash="7 4")
    g.ball(cx - 76, cy - 76, r=5); g.heb(cx - 100, cy - 112, "שלב 1"); g.text(cx - 100, cy - 96, "720 km")
    g.ball(cx + 76, cy - 76, r=5); g.heb(cx + 62, cy - 52, "שלב 2"); g.text(cx + 62, cy - 36, "410 km")
    return g

E(id="bagrut-2018-q6", year=2018, label="2018 שאלה 6", topic="gravitation", sub="grav-energy", diff=3, fig=fig,
  stem=r"סוכנות החלל הישראלית בשיתוף עם סוכנות החלל הצרפתית שיגרו באוגוסט 2017 לוויין זעיר שמכונה VENµS (Vegetation & Environment on New Micro Satellite) למטרות תצפית ומחקר ייחודי. הלוויין מצויד באמצעים טכנולוגיים משוכללים, שחלקם פותחו ויוצרו בישראל. הלוויין מצויד בשני מנועי סילון חדשניים שפותחו בישראל וייבחנו לראשונה בחלל. הלוויין מתוכנן לשהות בחלל כשלוש שנים וחצי: בשלב הראשון ינוע הלוויין בגובה של $720\,\text{km}$ מעל פני כדור הארץ, ובשלב השני ינוע בגובה של $410\,\text{km}$ מעל פני כדור הארץ. הנח כי הלוויין נע במסלול מעגלי, והתייחס רק להשפעת כדור הארץ על תנועת הלוויין. נתונים: מסת כדור הארץ $5.98 \times 10^{24}\,\text{kg}$, רדיוס כדור הארץ $6.37 \times 10^6\,\text{m}$.",
  parts=[
    P("א", r"חשב את תאוצת הנפילה החופשית של הלוויין במהלך תנועתו בשלב הראשון (גודל וכיוון).", num(a1, "m/s^2", tol=1), ["principle", "algebra"], [
        S(r"רדיוס המסלול", r"מהמרכז", r"r_1 = 6.37 \times 10^6 + 7.2 \times 10^5 = 7.09 \times 10^6\,\text{m}"),
        S(r"תאוצת הכבידה", r"מכוונת למרכז כדור הארץ", r"g^* = \frac{GM}{r_1^2} = \frac{6.67 \times 10^{-11} \cdot 5.98 \times 10^{24}}{(7.09 \times 10^6)^2} \approx 7.9\,\text{m/s}^2"),
    ], r"$\approx 7.9\,\text{m/s}^2$, אל מרכז כדור הארץ", key=r"g*=7.9 m/s²"),
    P("ב1", r"חשב את המהירות המשיקית של הלוויין במסלולו בשלב השני.", num(v2, "m/s", tol=1), ["principle", "algebra"], [
        S(r"כבידה ככוח צנטריפטלי", r"$r_2 = 6.37 \times 10^6 + 4.1 \times 10^5 = 6.78 \times 10^6\,\text{m}$", r"v = \sqrt{\frac{GM}{r_2}} = \sqrt{\frac{3.99 \times 10^{14}}{6.78 \times 10^6}} \approx 7.67 \times 10^3\,\text{m/s}"),
    ], r"$v \approx 7670\,\text{m/s}$", key=r"v=7661 m/s"),
    P("ב2", r"חשב את זמן המחזור (בשעות) של הלוויין במסלולו בשלב השני.", num(T2, "h", tol=1), ["algebra", "units"], [
        S(r"היקף חלקי מהירות", r"מהירות קבועה", r"T = \frac{2\pi r_2}{v} = \frac{2\pi \cdot 6.78 \times 10^6}{7670} \approx 5.55 \times 10^3\,\text{s}"),
        S(r"לשעות", r"מחלקים ב-3600", r"T \approx 1.54\,\text{h}"),
    ], r"$T \approx 1.54\,\text{h}$", key=r"T=1.547 hr"),
    P("ג1", r"קבע אם ההיגד נכון, שגוי או שאי אפשר לקבוע: האנרגיה הפוטנציאלית הכובדית של הלוויין בשלב הראשון גדולה מן האנרגיה הפוטנציאלית הכובדית שלו בשלב השני. נמק.", choice(TF, 0), ["principle", "signs"], [
        S(r"אנרגיה פוטנציאלית", r"שלילית, וקרובה לאפס ככל שהרדיוס גדל", r"E_p = -\frac{GMm}{r},\ r_1 > r_2 \Rightarrow E_{p1} > E_{p2}"),
    ], r"נכון"),
    P("ג2", r"קבע אם ההיגד נכון, שגוי או שאי אפשר לקבוע: האנרגיה הקינטית של הלוויין בשלב הראשון גדולה מן האנרגיה הקינטית שלו בשלב השני. נמק.", choice(TF, 1), ["principle"], [
        S(r"מהירות במסלול", r"ככל שהרדיוס קטן, המהירות גדלה", r"E_k = \frac{GMm}{2r},\ r_1 > r_2 \Rightarrow E_{k1} < E_{k2}"),
    ], r"שגוי", key=r"wrong"),
    P("ג3", r"קבע אם ההיגד נכון, שגוי או שאי אפשר לקבוע: האנרגיה הכוללת של הלוויין בשלב הראשון שווה לאנרגיה הכוללת שלו בשלב השני. נמק.", choice(TF, 1), ["principle", "signs"], [
        S(r"אנרגיה כוללת במסלול", r"תלויה ברדיוס", r"E = -\frac{GMm}{2r},\ r_1 > r_2 \Rightarrow E_1 > E_2"),
    ], r"שגוי: האנרגיה הכוללת בשלב הראשון גדולה יותר", key=r"not correct"),
    P("ד", r"(סעיף זה עוסק בלוויין דמיוני.) נתון לוויין שנע סביב כדור הארץ במסלול מעגלי שרדיוסו $6900\,\text{km}$. מסת הלוויין היא $300\,\text{kg}$. חשב את התוספת המינימלית של האנרגיה הנדרשת כדי לגרום ללוויין להגיע למצב שבו הוא יתנתק מהשפעת כוח המשיכה של כדור הארץ.", num(Ed, "J", tol=1), ["principle", "algebra"], [
        S(r"אנרגיה כוללת במסלול", r"קינטית ועוד פוטנציאלית", r"E = -\frac{GMm}{2r}"),
        S(r"להגיע לאנרגיה אפס", r"מינימום: מגיע לאינסוף במהירות אפס", r"\Delta E = \frac{GMm}{2r} = \frac{3.99 \times 10^{14} \cdot 300}{2 \cdot 6.9 \times 10^6} \approx 8.67 \times 10^9\,\text{J}"),
    ], r"$\approx 8.7 \times 10^9\,\text{J}$"),
  ],
  concepts=["תאוצת הכבידה בגובה", "מהירות במסלול", "אנרגיה במסלול", "אנרגיית מילוט"],
  summary=r"הלוויין VENµS בשני גבהים: תאוצה, מהירות וזמן מחזור, והשוואת אנרגיות בין המסלולים.")
